// Build the Anthropic request that asks Claude for a varied batch of mails.
const SYSTEM = "Tu generes des mails clients realistes et varies en francais pour le service ADV d'un vendeur de cuisines. Produis EXACTEMENT un tableau JSON de 6 objets {from, subject, body}, sans aucun texte autour. Varie les categories: demande de devis, relance de devis, reclamation/SAV (avec une reference commande type CDE-78xxx), demande d'information avant-vente, suivi de commande, annulation, et au moins un spam publicitaire. Ton naturel, 2 a 4 phrases, signatures plausibles, adresses en @example.com.";
return [{ json: { anthropicBody: { model: 'claude-opus-4-8', max_tokens: 2000, system: SYSTEM, messages: [ { role: 'user', content: 'Genere le lot de mails maintenant.' } ] } } }];

// Parse Claude's JSON array into one n8n item per mail.
const text = ($json.content && $json.content[0]) ? $json.content[0].text : '[]';
const clean = text.replace(/^```(json)?/m, '').replace(/```$/m, '').trim();
let arr;
try { arr = JSON.parse(clean); } catch (e) { arr = []; }
return arr.map(m => ({ json: { from: m.from || 'client@example.com', subject: m.subject || '(sans objet)', body: m.body || '' } }));
